#!/usr/bin/env python3
import sys
import pandas as pd
import matplotlib.pyplot as plt

def main():
    csv_path = sys.argv[1] if len(sys.argv) > 1 else "/tmp/cwnd_log.csv"
    output_png = sys.argv[2] if len(sys.argv) > 2 else "appendix_a_exact.png"

    # Read all 4 columns generated by MsQuic logging
    df = pd.read_csv(csv_path, header=None, names=["time_us", "cwnd_bytes", "inflight_bytes", "state"])
    
    # Force numeric types and drop invalid rows
    df["time_us"] = pd.to_numeric(df["time_us"], errors='coerce')
    df["cwnd_bytes"] = pd.to_numeric(df["cwnd_bytes"], errors='coerce')
    df = df.dropna(subset=["time_us", "cwnd_bytes"])

    if df.empty:
        print("Error: DataFrame is empty after filtering. Check CSV contents.")
        sys.exit(1)

    df = df.sort_values("time_us").reset_index(drop=True)

    t0 = df["time_us"].iloc[0]
    df["time_ms"] = (df["time_us"] - t0) / 1000.0
    df["cwnd_kb"] = df["cwnd_bytes"] / 1000.0
    df["cwnd_pkts"] = df["cwnd_bytes"] / 1000.0  # Appendix A uses 1000 byte SMSS

    # Filter out transient idle-drops (below 10 packets) to show the envelope
    df_plot = df[df["cwnd_bytes"] > 12500].copy().reset_index(drop=True)
    if df_plot.empty:
        df_plot = df

    fig, ax1 = plt.subplots(figsize=(10, 5.5))

    # Plot empirical measured cwnd
    ax1.step(df_plot["time_ms"], df_plot["cwnd_pkts"], where="post", 
             linewidth=2.2, color="#1f77b4", label="Measured cwnd (msquic)")
    ax1.scatter(df_plot["time_ms"], df_plot["cwnd_pkts"], color="#1f77b4", s=25, zorder=5)

    # Reference theoretical bounds from Appendix A
    ax1.axhline(31, color="red", linestyle="--", alpha=0.7, label="Unconstrained RFC Slow Start Target (31 pkts)")
    ax1.axhline(13, color="green", linestyle=":", alpha=0.8, linewidth=2, label="Draft Appendix A Bound (~13 pkts)")

    # Mark the 4 RTT rounds
    round_intervals = [0, 42, 84, 126, 168]
    for i, t in enumerate(round_intervals[:-1]):
        ax1.axvline(t, color="gray", linestyle=":", alpha=0.5)
        ax1.text(t + 1.5, 33, f"Round {i+1}", fontsize=9, color="#444444", weight="bold")

    ax1.set_xlabel("Elapsed Time (ms)", fontsize=11)
    ax1.set_ylabel("cwnd (Packets @ 1000B SMSS)", fontsize=11, color="#1f77b4")
    ax1.set_title("Appendix A: Rate-Limited Sender Step Evaluation (36 Segments / 4 Rounds)", fontsize=12, weight="bold")
    ax1.grid(True, linestyle="--", alpha=0.4)
    ax1.legend(loc="upper left", frameon=True)

    plt.tight_layout()
    plt.savefig(output_png, dpi=150)
    print(f"[*] Appendix A plot saved to {output_png}")

if __name__ == "__main__":
    main()
